const container=document.getElementById("cherryBlossomContainer"),blossomCount=15;function createCherryBlossom(){const e=document.createElement("div");e.className="cherry-blossom";const t=100*Math.random();e.style.left=t+"%",e.style.top="-50px";const o=8+8*Math.random(),s=5*Math.random();e.style.animation=`fall ${o}s linear ${s}s infinite`,container.appendChild(e),setTimeout(()=>{e.remove()},1e3*(o+s))}function initCherryBlossoms(){for(let e=0;e<15;e++)setTimeout(()=>{createCherryBlossom()},200*e);setInterval(()=>{createCherryBlossom()},500)}initCherryBlossoms();